<script setup>
import {computed,onMounted,ref} from 'vue';
import api from '../services/api';
import AppIcon from '../components/common/AppIcon.vue';

const current=ref(null),years=ref([]),preview=ref(null),openingBalances=ref({cash:0,bank_transfer:0,card:0,other:0}),loading=ref(true),previewLoading=ref(false),savingOpenings=ref(false),closing=ref(false),error=ref(''),notice=ref('');
const money=value=>'PKR '+Number(value||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
const date=value=>value?new Date(value).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}):'—';
const canClose=computed(()=>current.value&&current.value.status==='active'&&new Date().toISOString().slice(0,10)>=String(current.value.end_date).slice(0,10));
async function load(){loading.value=true;try{const {data}=await api.get('/financial-years');current.value=data.data.current;years.value=data.data.years;if(current.value)await loadPreview(current.value)}catch(e){error.value=e.response?.data?.message||'Unable to load financial years.'}finally{loading.value=false}}
async function loadPreview(year){previewLoading.value=true;error.value='';try{preview.value=(await api.get(`/financial-years/${year.id}/preview`)).data.data;openingBalances.value=Object.fromEntries(preview.value.balances.account_balances.map(row=>[row.account_key,Number(row.opening||0)]))}catch(e){error.value=e.response?.data?.message||'Unable to calculate closing balances.'}finally{previewLoading.value=false}}
async function saveOpenings(){if(!current.value)return;savingOpenings.value=true;error.value='';try{const account_balances=['cash','bank_transfer','card','other'].map(account_key=>({account_key,opening_balance:Number(openingBalances.value[account_key]||0)}));preview.value=(await api.put(`/financial-years/${current.value.id}/openings`,{account_balances})).data.data;notice.value='Opening account balances updated.'}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||'Unable to update opening balances.'}finally{savingOpenings.value=false}}
async function closeYear(){if(!current.value)return;const message=`Close financial year ${current.value.name}? This locks its accounting entries and carries all closing balances into the next year.`;if(!confirm(message))return;closing.value=true;error.value='';try{const {data}=await api.post(`/financial-years/${current.value.id}/close`);notice.value=data.message;setTimeout(()=>location.reload(),900)}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||'Unable to close financial year.'}finally{closing.value=false}}
onMounted(load);
</script>

<template><div class="page-head"><div><span class="eyebrow">Accounting control</span><h1>Financial years</h1><p class="page-subtitle">Control the active accounting session and verify balances before closing.</p></div></div><div v-if="notice" class="success-message">{{notice}}</div><div v-if="error" class="error">{{error}}</div><div v-if="loading" class="panel empty-state">Loading financial years…</div><template v-else-if="current"><section class="financial-year-hero panel"><div><span class="status success">Current session</span><h2>{{current.name}}</h2><p>{{date(current.start_date)}} — {{date(current.end_date)}}</p></div><div class="year-close-action"><button class="with-icon" :disabled="!canClose||closing" @click="closeYear"><AppIcon name="close"/>{{closing?'Closing year…':'Close financial year'}}</button><small v-if="!canClose">Closing becomes available on {{date(current.end_date)}}.</small><small v-else>Closing is permanent and opens the next session automatically.</small></div></section><div v-if="previewLoading" class="panel empty-state">Calculating opening and closing balances…</div><template v-else-if="preview"><div class="report-summary"><div class="summary-card"><span>Customer receivables</span><strong>{{money(preview.balances.summary.customer_receivables)}}</strong></div><div class="summary-card"><span>Supplier payables</span><strong>{{money(preview.balances.summary.supplier_payables)}}</strong></div><div class="summary-card"><span>Inventory value</span><strong>{{money(preview.balances.summary.inventory_value)}}</strong></div><div class="summary-card"><span>Cash / bank closing</span><strong>{{money(preview.balances.summary.cash_bank_balance)}}</strong></div><div class="summary-card"><span>Operating expenses</span><strong>{{money(preview.balances.summary.expenses)}}</strong></div></div><div class="financial-year-balance-grid"><section class="panel list-panel"><div class="panel-head"><div><h2>Cash and bank carry-forward</h2><p>Opening + receipts − payments = closing</p></div><button v-if="preview.financial_year.id===current.id" class="secondary with-icon" :disabled="savingOpenings" @click="saveOpenings"><AppIcon name="save"/>{{savingOpenings?'Saving…':'Save openings'}}</button></div><table><thead><tr><th>Channel</th><th class="number">Opening</th><th class="number">Received</th><th class="number">Paid</th><th class="number">Closing</th></tr></thead><tbody><tr v-for="row in preview.balances.account_balances"><td><strong>{{row.account_key.replaceAll('_',' ')}}</strong></td><td class="number"><input v-if="preview.financial_year.id===current.id" v-model.number="openingBalances[row.account_key]" class="opening-balance-input" type="number" step="0.01"><template v-else>{{money(row.opening)}}</template></td><td class="number">{{money(row.received)}}</td><td class="number">{{money(row.paid)}}</td><td class="number"><strong>{{money(row.closing)}}</strong></td></tr></tbody></table></section><section class="panel list-panel"><div class="panel-head"><div><h2>Party balances</h2><p>Largest balances that move into the next year</p></div></div><table><thead><tr><th>Type / party</th><th class="number">Opening</th><th class="number">Movement</th><th class="number">Closing</th></tr></thead><tbody><tr v-for="row in [...preview.balances.customer_balances,...preview.balances.supplier_balances].sort((a,b)=>b.closing-a.closing).slice(0,10)"><td><strong>{{row.party}}</strong></td><td class="number">{{money(row.opening)}}</td><td class="number">{{money(row.movement)}}</td><td class="number"><strong>{{money(row.closing)}}</strong></td></tr><tr v-if="!preview.balances.customer_balances.length&&!preview.balances.supplier_balances.length"><td colspan="4" class="empty-state">No party balances.</td></tr></tbody></table></section></div></template><section class="panel list-panel year-history"><div class="panel-head"><div><h2>Financial-year history</h2><p>Closed years remain available through Reports.</p></div></div><table><thead><tr><th>S. No.</th><th>Financial year</th><th>Period</th><th>Status</th><th>Closed by</th><th>Closed at</th><th>Review</th></tr></thead><tbody><tr v-for="(year,index) in years" :key="year.id"><td>{{index+1}}</td><td><strong>{{year.name}}</strong></td><td>{{date(year.start_date)}} — {{date(year.end_date)}}</td><td><span class="status" :class="year.status==='active'?'success':'neutral'">{{year.status}}</span></td><td>{{year.closed_by?.name||'—'}}</td><td>{{date(year.closed_at)}}</td><td><button class="icon-only secondary" title="Preview balances" @click="loadPreview(year)"><AppIcon name="eye"/></button></td></tr></tbody></table></section></template></template>
